#!/bin/bash
# 合成音声のテスト素材を作り直す(macOS の say・Kyoko)。[[slnc ms]] は無音。
set -euo pipefail
cd "$(dirname "$0")"
say -v Kyoko -o meeting_ja.aiff "本日はご説明ありがとうございます。全体像はよく分かりました。 [[slnc 1400]] まず確認ですが、この構成でグローバルプロテクトの分割トンネルはどう扱いますか。 [[slnc 2500]] なるほど、承知しました。 [[slnc 1200]] 次に、導入にかかる費用はどのくらいでしょうか。 [[slnc 2500]] ありがとうございます。 [[slnc 1200]] 最後に、既存のシームと競合するリスクはありませんか。 [[slnc 2500]] 以上です。"
say -v Kyoko -o statement_ja.aiff "今日の議題は三つあります。一つ目は来期の体制について、二つ目はセキュリティ監視の改善、三つ目は採用計画です。"
ls -la *.aiff
